<?php
if(PHP_SAPI!=='cli')exit(1);$zip=new ZipArchive();if($zip->open($argv[1])!==true)throw new RuntimeException('ZIP invalid.');$count=0;
for($i=0;$i<$zip->numFiles;$i++)if(str_ends_with($zip->getNameIndex($i),'.csv')){$text=$zip->getFromIndex($i);if(!str_starts_with($text,"\xEF\xBB\xBFsep=;\r\n"))throw new RuntimeException('Missing Excel UTF-8 delimiter hint.');$stream=fopen('php://temp','w+');fwrite($stream,substr($text,10));rewind($stream);$header=fgetcsv($stream,0,';','"','');if($header!==['url','wp_id','locale','content_type','status','last_modified_utc'])throw new RuntimeException('CSV metadata headers invalid: '.json_encode($header));while(($row=fgetcsv($stream,0,';','"',''))!==false){if(count($row)!==6 || $row[2]!=='vi' || $row[3]!=='post' || $row[4]!=='publish' || !preg_match('/Z$/',$row[5]))throw new RuntimeException('CSV frozen metadata invalid.');$count++;}fclose($stream);}
if(!$count)throw new RuntimeException('No CSV data.');echo json_encode(['rows'=>$count,'columns'=>6]);
